section.programlisting:
function shout(word: String) returns String
{
    print word          ; error: function shout performs I/O
    word
}

function square(x: int) returns int x * x
let n 1000 var squares Vector[int](n as size_t) for i in n squares.put(i as size_t, square(i))
var total 0 for s in squares total := total + s print "sum of squares below `n`: `total`"
